package dev.zomboid.clans;
import java.util.*;import net.minecraft.server.*;import net.minecraft.server.level.*;import net.minecraft.nbt.*;import net.minecraft.core.*;import me.danialisntcool.factionfriction.faction.*;
public class PveChecks {
 public static class Team {Object color;public void setColor(Object c){color=c;}}
 public static class Scoreboard {Team team;Set<String> entries=new HashSet<>();public Team getPlayerTeam(String n){return team;}public Team addPlayerTeam(String n){return team=new Team();}public boolean addPlayerToTeam(String n,Object t){return entries.add(n);}public void removePlayerFromTeam(String n){entries.remove(n);}}

 static int n;static void ok(boolean b,String message){n++;if(!b)throw new AssertionError(message);}
 public static class World extends ServerPlayer.Level {Scoreboard board=new Scoreboard();public Scoreboard getScoreboard(){return board;}MinecraftServer server;BlockPos nexus=new BlockPos(0,60,0);boolean destroyed;World(MinecraftServer server){this.server=server;}public boolean isClientSide(){return false;}public MinecraftServer getServer(){return server;}public Object getEntity(UUID uuid){return null;}public boolean destroyBlock(Object p,boolean drops){destroyed=true;return true;}public Hit clip(Object context){return new Hit(nexus);}public boolean hasChunkAt(Object pos){return true;}public State getBlockState(Object p){return new State(Nexus.BLOCK);}}
 public record Hit(BlockPos pos){public String getType(){return "BLOCK";}public BlockPos getBlockPos(){return pos;}}
 public record State(Object block){public Object getBlock(){return block;}}
 public static class Player extends ServerPlayer {World world;CompoundTag data=new CompoundTag();boolean alive=true;public Player(MinecraftServer s,World w){super(s);world=w;}public World level(){return world;}public boolean isAlive(){return alive;}public void displayClientMessage(Object message,boolean overlay){}public CompoundTag getPersistentData(){return data;}}
 public static class Navigation {int moves;public boolean moveTo(double x,double y,double z,double speed){moves++;return true;}}
 public static class Look {public void setLookAt(double x,double y,double z){}}
 public static class Mob extends net.minecraft.world.entity.Mob {boolean glowing;public void setGlowingTag(boolean value){glowing=value;}World world;CompoundTag tag=new CompoundTag();String type="minecraft:zombie";UUID id=UUID.randomUUID();Navigation nav=new Navigation();public Mob(World w){world=w;}public World level(){return world;}public CompoundTag getPersistentData(){return tag;}public Object getType(){return type;}public UUID getUUID(){return id;}public net.minecraft.world.level.ChunkPos chunkPosition(){return new net.minecraft.world.level.ChunkPos(0,0);}public Navigation getNavigation(){return nav;}public Look getLookControl(){return new Look();}public Object getEyePosition(){return new net.minecraft.world.phys.Vec3(0,61,0);}public double distanceToSqr(double x,double y,double z){return 4;}public void swing(Object hand){}public void discard(){} }
 public static class Join {World w;Mob e;boolean canceled,loaded;Join(World w,Mob e){this.w=w;this.e=e;}public World getLevel(){return w;}public Mob getEntity(){return e;}public boolean loadedFromDisk(){return loaded;}public void setCanceled(boolean b){canceled=b;}}
 public record Source(Object entity){public Object getEntity(){return entity;}}
 public record Death(Object entity,Source source){public boolean isCanceled(){return false;}public Object getEntity(){return entity;}public Source getSource(){return source;}}
 public static class BlockEvent {World w;Player p;boolean canceled;BlockEvent(World w,Player p){this.w=w;this.p=p;}public World getLevel(){return w;}public Player getEntity(){return p;}public Player getPlayer(){return p;}public State getPlacedBlock(){return new State(Nexus.BLOCK);}public State getState(){return getPlacedBlock();}public BlockPos getPos(){return w.nexus;}public void setCanceled(boolean b){canceled=b;}}
 public static class Register {Object key;Map<Object,Object> values=new HashMap<>();Register(Object key){this.key=key;}public Object getRegistryKey(){return key;}public void register(Object key,java.util.function.Consumer<Helper> consumer){consumer.accept(new Helper(values));}}
 public record Helper(Map<Object,Object> values){public void register(Object key,Object value){values.put(key,value);}}
 public static class Tooltip {Object item;List<Object> lines=new ArrayList<>();Tooltip(Object item){this.item=item;}public Object getItemStack(){return new Stack(item);}public List<Object> getToolTip(){return lines;}}
 public record Stack(Object item){public Object getItem(){return item;}}
 public static void main(String[]args){Register blocks=new Register(net.minecraft.core.registries.Registries.BLOCK),items=new Register(net.minecraft.core.registries.Registries.ITEM);Nexus.register(blocks);Nexus.register(items);Object goal=Nexus.goal(new Object());ok(goal instanceof NexusGoal,"reflective goal class loads with dotted name");ok(((NexusGoal)goal).getFlags().containsAll(java.util.Set.of(net.minecraft.world.entity.ai.goal.Goal.Flag.MOVE,net.minecraft.world.entity.ai.goal.Goal.Flag.LOOK)),"goal movement flags configured");Tooltip tooltip=new Tooltip(Nexus.ITEM);Nexus.tooltip(tooltip);ok(tooltip.lines.size()==8,"nexus explanation tooltip");Tooltip other=new Tooltip(new Object());Nexus.tooltip(other);ok(other.lines.isEmpty(),"unrelated item tooltip unchanged");ok(blocks.values.size()==1&&items.values.size()==1,"block and item registration");ok(((net.minecraft.world.item.BlockItem)Nexus.ITEM).block==Nexus.BLOCK,"placeable item linked to block");ok(((net.minecraft.world.level.block.Block)Nexus.BLOCK).properties.resistance==3600000,"explosion resistance");ok(Limits.maximum(FactionTier.TEAM)==4,"level 1 limit");ok(Limits.maximum(FactionTier.COLONY)==6,"level 2 limit");ok(Limits.maximum(FactionTier.COUNTRY)==8,"level 3 limit");int[] frequencies=new int[5];for(int i=0;i<100;i++)frequencies[PveRules.rarity(i)]++;ok(Arrays.equals(frequencies,new int[]{60,25,10,4,1}),"rarity probabilities");ok(PveRules.level(99)==1&&PveRules.level(100)==2&&PveRules.level(299)==2&&PveRules.level(300)==3,"XP thresholds");ClanState.Profile base=new ClanState.Profile();ok(Nexus.maxHealth(base)==100,"base health");base.nexusUpgrade=10;ok(Nexus.maxHealth(base)==350,"upgrade health");MinecraftServer server=new MinecraftServer();World world=new World(server);Player chief=new Player(server,world);Faction faction=new Faction("Tribe");Faction capped=new Faction("Cap");for(long i=0;i<4;i++)capped.claims.add(i);ok(!Limits.room(capped,1),"no new claim at cap");capped.claims.remove(3L);ok(Limits.room(capped,1)&&!Limits.room(capped,2),"reserved capture capacity");Faction defender=new Faction("Defender");defender.claims.add(0L);defender.claims.add(1L);defender.capital.add(0L);ok(!Limits.attack(new OperationAttack(0,0),capped,defender),"capital annexation cannot exceed cap");faction.members.put(chief.uuid,FactionRank.CREATOR);faction.claims.add(0L);server.manager.factions.put(faction.id,faction);server.manager.owners.put(0L,faction.id);Clans.bind(server.manager,server);ClanState.Profile profile=Clans.state(server.manager).profile(faction.id);Nexus.BLOCK=new Object();BlockEvent place=new BlockEvent(world,chief);Nexus.place(place);ok(!place.canceled&&profile.nexusPlaced,"placement in claimed territory");BlockEvent duplicate=new BlockEvent(world,chief);Nexus.place(duplicate);ok(duplicate.canceled,"single nexus");Pve.Wave wave=new Pve.Wave(faction.id,world,0,0,0);wave.health=100;wave.participants.add(chief.uuid);Pve.waves.put(faction.id,wave);BlockEvent breaking=new BlockEvent(world,chief);Nexus.breakBlock(breaking);ok(breaking.canceled,"no player break during defense");Mob zombie=new Mob(world);Pve.outline(world,zombie);ok(zombie.glowing&&world.board.team.color==net.minecraft.ChatFormatting.RED&&world.board.entries.contains(zombie.id.toString()),"wave enemies have red glowing outline");Pve.clearOutline(world,zombie.id);ok(world.board.entries.isEmpty(),"outline scoreboard entries cleaned");Join natural=new Join(world,zombie);Pve.join(natural);ok(natural.canceled,"natural zombie blocked in claimed chunk");Join loaded=new Join(world,zombie);loaded.loaded=true;Pve.join(loaded);ok(!loaded.canceled,"existing saved entity kept");zombie.tag.putString("FactionPveWave",wave.id.toString());Join permitted=new Join(world,zombie);Pve.join(permitted);ok(!permitted.canceled,"defense zombie permitted");profile.nexusPos=world.nexus.asLong();Nexus.mobTick(zombie);ok(wave.health==95,"zombie hit 5");server.time=1;Nexus.mobTick(zombie);ok(wave.health==95,"individual hit cooldown");server.time=20;zombie.type="mutantszombies:mutant_brute";Nexus.mobTick(zombie);ok(wave.health==85,"mutant hit 10");wave.pending=0;wave.alive=0;server.time=21;Pve.tick(server);ok(wave.stage==2&&wave.pending==12&&wave.health==85,"next phase retains nexus life with offset clock");wave.pending=0;wave.alive=0;Pve.tick(server);ok(wave.stage==3&&wave.health==85,"third phase retains life");wave.pending=0;wave.alive=0;wave.killed=36;Pve.tick(server);ok(!Pve.waves.containsKey(faction.id)&&profile.pveXp==20&&profile.pveWins==1,"completed run rewards once");ok(profile.pveNext==6021&&!profile.rewards.isEmpty(),"five minute cooldown and loot");Pve.tick(server);ok(profile.pveWins==1,"no duplicate reward");Pve.end(server,server.manager,wave,true);ok(profile.pveWins==1&&profile.pveXp==20,"repeated finalization cannot pay twice");Pve.Wave next=new Pve.Wave(faction.id,world,0,1,server.time);next.health=Nexus.maxHealth(profile);next.participants.add(chief.uuid);Pve.waves.put(faction.id,next);ok(next.health==100,"new run resets health");Pve.death(new Death(chief,new Source(zombie)));ok(!Pve.waves.containsKey(faction.id)&&profile.pveWins==1,"all participant deaths fail without rewards");Pve.Wave destroyed=new Pve.Wave(faction.id,world,0,0,0);destroyed.health=5;destroyed.participants.add(chief.uuid);Pve.waves.put(faction.id,destroyed);zombie.tag.putString("FactionPveWave",destroyed.id.toString());server.time=40;Nexus.mobTick(zombie);ok(world.destroyed&&!profile.nexusPlaced&&!Pve.waves.containsKey(faction.id),"nexus destroyed fails");CompoundTag saved=new CompoundTag();profile.nexusUpgrade=3;Clans.save(server.manager,saved);me.danialisntcool.factionfriction.data.FactionManager restored=new me.danialisntcool.factionfriction.data.FactionManager();Clans.load(restored,saved);ClanState.Profile restoredProfile=Clans.state(restored).profile(faction.id);ok(restoredProfile.pveXp==20&&restoredProfile.pveWins==1&&restoredProfile.nexusUpgrade==3,"XP ranking and upgrades persist");System.out.println("PASS "+n+" nexus, PvE and territorial checks (API doubles)");}
}
